{

"kind": "propose",
"summary": "Adjust liveness probe timeout and initial delay to match application startup time",
"hypotheses": [
  {
    "root_cause_class": "probe_too_strict_for_startup",
    "summary": "Liveness probe fails before application completes startup",
    "supporting": ["probe_kills", "killed_during_startup", "ev-container_logs_tail"],
    "contradicting": ["probe_timeouts"],
    "missing": ["application_startup_time_ms"],
    "status": "supported"
  },
  {
    "root_cause_class": "insufficient_evidence",
    "summary": "No metrics history to confirm rollout impact",
    "supporting": ["failures_came_with_rollout"],
    "contradicting": [],
    "missing": ["metrics_history"],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "finance",
    "name": "ledger",
    "uid": "uid-deployment-ledger"
  },
  "params": {
    "container": "app",
    "liveness": {
      "initialDelaySeconds": 30,
      "timeoutSeconds": 10
    }
  },
  "expected_effect": "Allow application to complete startup before liveness probe fails",
  "rationale": "Pods ran 32s before being killed, indicating startup takes longer than current 10s delay and 1s timeout. Increasing initial delay to 30s and timeout to 10s matches the 32s startup time shown in logs, preventing premature probe failures.",
  "cited_evidence_ids": ["ev-rollout_history", "ev-pod_states", "ev-target_events", "ev-container_logs_tail"],
  "cited_predicates": ["killed_during_startup", "probe_kills"]
}
}
